solution.query.js:
// Parse a query string into an object. Repeated keys become arrays.
export function parseQuery(s) {
  const out = {};
  for (const [k, v] of new URLSearchParams(s)) {
    if (!(k in out)) out[k] = v;
    else out[k] = [].concat(out[k], v);
  }
  return out;
}
